style.css:
@-moz-document domain("roblox.com") {
/* ===== Full-page background image ===== */
    html, body, #container-main, #content, .rbx-body, .container-main, .page-content, .content, .game-home-page-content, .profile-container, .section-content, .section-header, .container-section {
        background: url("https://i.imgur.com/hbvV4gl.jpe") no-repeat center center fixed !important;
        background-size: cover !important;
        background-color: transparent !important;
    }

    /* ===== Navbar styling ===== */
    .navbar, .nav-container, header {
        background: rgba(0,0,0,0.65) !important;
        backdrop-filter: blur(6px) !important;
        border: none !important;
    }

    /* ===== Panels / cards ===== */
    .game-card, .profile-header-content, .container-section, .content-section, .card, .card-container {
        background: rgba(0, 0, 0, 0.55) !important;
        border-radius: 10px !important;
    }

    /* ===== Text colors ===== */
    h1, h2, h3, h4, h5, h6, p, span, a, div, button {
        color: #fff !important;
        text-shadow: 0 0 6px rgba(0,0,0,0.8) !important;
    }

    /* ===== Remove ads / banners / footer ===== */
    .ads-container, .cookie-banner, .footer-container, .age-verification-banner {
        display: none !important;
    }

    /* ===== Remove blue outlines ===== */
    *:focus {
        outline: none !important;
        box-shadow: none !important;
    }
}
